def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Locate the full-width and full-height divider lines.
    divider = None
    row_lines = []
    col_lines = []
    for r, row in enumerate(g):
        if row[0] != 0 and all(x == row[0] for x in row):
            row_lines.append(r)
            divider = row[0]
    for c in range(w):
        val = g[0][c]
        if val != 0 and all(g[r][c] == val for r in range(h)):
            col_lines.append(c)
            divider = val

    if not row_lines or not col_lines:
        return g

    row_bounds = [-1] + row_lines + [h]
    col_bounds = [-1] + col_lines + [w]
    cells = []
    for i in range(len(row_bounds) - 1):
        row = []
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            row.append((r0, r1, c0, c1))
        cells.append(row)

    def colors(cell):
        r0, r1, c0, c1 = cell
        return {g[r][c] for r in range(r0, r1) for c in range(c0, c1)
                if g[r][c] != 0 and g[r][c] != divider}

    # In each 2x2 group with three matching occupied cells, complete the
    # missing cell by reflecting the diagonally opposite pattern both ways.
    for i in range(len(cells) - 1):
        for j in range(len(cells[i]) - 1):
            block = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
            occupied = [(a, b, colors(cells[a][b])) for a, b in block]
            empty = [(a, b) for a, b, cs in occupied if not cs]
            filled = [(a, b, cs) for a, b, cs in occupied if cs]
            if len(empty) != 1 or len(filled) != 3:
                continue
            color_sets = [cs for _, _, cs in filled]
            if any(len(cs) != 1 for cs in color_sets) or not (
                color_sets[0] == color_sets[1] == color_sets[2]
            ):
                continue

            ti, tj = empty[0]
            si, sj = 2 * i + 1 - ti, 2 * j + 1 - tj
            sr0, sr1, sc0, sc1 = cells[si][sj]
            tr0, tr1, tc0, tc1 = cells[ti][tj]
            if sr1 - sr0 != tr1 - tr0 or sc1 - sc0 != tc1 - tc0:
                continue

            rh, cw = sr1 - sr0, sc1 - sc0
            for dr in range(rh):
                for dc in range(cw):
                    value = g[sr1 - 1 - dr][sc1 - 1 - dc]
                    if value != 0 and value != divider:
                        g[tr0 + dr][tc0 + dc] = value

    return g
